// uart_item.sv - generated by uvm_full_tb_generator.py, filled in with UART protocol fields
//   One item = one character on the serial line (8N1, LSB first).

typedef enum bit { UART_PC_TO_SOC = 1'b0,   // on uart_rx_i : the VIP driver sends it
                   UART_SOC_TO_PC = 1'b1    // on uart_tx_o : the VIP monitor sees it
                 } uart_dir_e;

class uart_item extends uvm_sequence_item;

  rand bit [7:0]    data;          // the byte
  uart_dir_e        dir;           // set by the monitor

  // error injection (driver)
  rand bit          inject_err;    // 1 = flip one data bit on the wire
  rand int unsigned err_bit;       // which bit (0..7)
  rand int unsigned idle_bits;     // idle bit times before the start bit

  // status (monitor)
  bit               framing_err;   // stop bit was 0

  constraint c_err  { soft inject_err == 0; err_bit < 8; }
  constraint c_idle { idle_bits inside {[0:2]}; }

  `uvm_object_utils_begin(uart_item)
    `uvm_field_int (data,        UVM_ALL_ON | UVM_HEX)
    `uvm_field_enum(uart_dir_e, dir, UVM_ALL_ON)
    `uvm_field_int (inject_err,  UVM_ALL_ON)
    `uvm_field_int (err_bit,     UVM_ALL_ON | UVM_DEC)
    `uvm_field_int (framing_err, UVM_ALL_ON)
  `uvm_object_utils_end

  function new(string name="uart_item"); super.new(name); endfunction

  function string convert2string();
    string c = (data >= 8'h20 && data < 8'h7f) ? $sformatf("'%c'", data) : "   ";
    return $sformatf("%s 0x%02h %s%s%s",
                     dir == UART_PC_TO_SOC ? "PC->SoC" : "SoC->PC", data, c,
                     inject_err  ? $sformatf(" [bit%0d flipped]", err_bit) : "",
                     framing_err ? " [FRAMING ERROR]" : "");
  endfunction
endclass
